#include <SDL2/SDL.h>
#include <string.h>
#include <stdint.h>

#define PG_EVENT_NONE        0
#define PG_EVENT_QUIT        1
#define PG_EVENT_KEYDOWN     2
#define PG_EVENT_KEYUP       3
#define PG_EVENT_MOUSEMOTION 4
#define PG_EVENT_MOUSEDOWN   5
#define PG_EVENT_MOUSEUP     6

typedef struct {
    int32_t event_type;
    int32_t key_code;
    int32_t mouse_x;
    int32_t mouse_y;
    int32_t mouse_button;
} pg_event_t;

_Static_assert(sizeof(pg_event_t) == 20, "struct must be 20 bytes for COBOL mapping");

static SDL_Window   *g_window   = NULL;
static SDL_Renderer *g_renderer = NULL;

static void cobol_to_cstr(const char *src, int len, char *dst, int dst_sz) {
    int n = len < dst_sz - 1 ? len : dst_sz - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
    while (n > 0 && dst[n - 1] == ' ') dst[--n] = '\0';
}

int pg_init(void) {
    return SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) == 0 ? 0 : -1;
}

void pg_quit(void) {
    if (g_renderer) { SDL_DestroyRenderer(g_renderer); g_renderer = NULL; }
    if (g_window)   { SDL_DestroyWindow(g_window);     g_window   = NULL; }
    SDL_Quit();
}

int pg_open_window(int w, int h, const char *title, int title_len) {
    char buf[256];
    cobol_to_cstr(title, title_len, buf, sizeof buf);

    g_window = SDL_CreateWindow(buf,
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        w, h, SDL_WINDOW_RESIZABLE);
    if (!g_window) return -1;

    g_renderer = SDL_CreateRenderer(g_window, -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!g_renderer) {
        SDL_DestroyWindow(g_window);
        g_window = NULL;
        return -1;
    }
    return 0;
}

