#include <stdio.h>
#include <stdint.h>

static void put16(FILE *f, uint16_t v) { fwrite(&v, 2, 1, f); }
static void put32(FILE *f, uint32_t v) { fwrite(&v, 4, 1, f); }

int main(void) {
    const int W = 48, H = 48;
    const int row_bytes = W * 3;          /* 144, already 4-byte aligned */
    const int data_size = row_bytes * H;

    FILE *f = fopen("test.bmp", "wb");
    if (!f) { perror("test.bmp"); return 1; }

    /* BMP file header (14 bytes) */
    fputc('B', f); fputc('M', f);
    put32(f, (uint32_t)(54 + data_size)); /* file size  */
    put32(f, 0);                          /* reserved   */
    put32(f, 54);                         /* data offset*/

    /* BITMAPINFOHEADER (40 bytes) */
    put32(f, 40);
    put32(f, (uint32_t)W);
    put32(f, (uint32_t)H);               /* positive = bottom-up */
    put16(f, 1);                          /* planes   */
    put16(f, 24);                         /* bpp      */
    put32(f, 0);                          /* compression (BI_RGB) */
    put32(f, 0); put32(f, 0); put32(f, 0); put32(f, 0); put32(f, 0);

    /* pixel data — bottom-up, BGR order */
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            uint8_t r, g, b;

            /* 2-pixel white border */
            if (x < 2 || x >= W - 2 || y < 2 || y >= H - 2) {
                r = 255; g = 255; b = 255;
            }
            /* red cross through the centre */
            else if ((x >= 18 && x < 30) || (y >= 18 && y < 30)) {
                r = 220; g = 40;  b = 40;
            }
            /* blue field */
            else {
                r = 40;  g = 100; b = 220;
            }

            fputc(b, f); fputc(g, f); fputc(r, f);  /* BMP = BGR */
        }
    }

    fclose(f);
    return 0;
}

